const PRIORIDADES = ['baixa', 'media', 'alta']
const PAGINA_PADRAO = 10
const PAGINA_MAXIMA = 50
const STATUS = ['aberto', 'fechado']

let proximoId = 1
let tickets = []

function zerar() {
  proximoId = 1
  tickets = []
}

// Um lugar so monta o corpo de erro: e o que mantem o formato igual nos tres.
function erro(status, mensagem, codigo) {
  return [status, { erro: mensagem, codigo }]
}

function criar(corpo) {
  const titulo = (corpo.titulo ?? '').trim()
  if (titulo === '') return erro(422, 'titulo é obrigatório', 'validacao')
  if (titulo.length > 140) return erro(422, 'titulo tem no máximo 140 caracteres', 'validacao')

  const prioridade = corpo.prioridade ?? 'media'
  if (!PRIORIDADES.includes(prioridade)) return erro(422, 'prioridade inválida', 'validacao')

  // So escreve depois que tudo passou.
  const ticket = { id: proximoId++, titulo, prioridade, status: 'aberto' }
  tickets.push(ticket)
  return [201, ticket]
}

function listar(parametros = {}) {
  const { status } = parametros
  if (status !== undefined && !STATUS.includes(status)) {
    return erro(422, 'status inválido', 'validacao')
  }

  const casam = tickets.filter((t) => status === undefined || t.status === status)

  const pagina = Math.max(1, parametros.pagina ?? 1)
  const tamanho = Math.min(parametros.tamanho ?? PAGINA_PADRAO, PAGINA_MAXIMA)
  const inicio = (pagina - 1) * tamanho

  // total e do filtro, nao da pagina: e o que diz a quem chama se ha mais.
  return [200, { itens: casam.slice(inicio, inicio + tamanho), pagina, total: casam.length }]
}

function fechar(id) {
  const ticket = tickets.find((t) => t.id === id)
  if (!ticket) return erro(404, 'ticket não encontrado', 'nao_encontrado')

  // Idempotente: ja fechado nao e erro, e o resultado e o mesmo.
  ticket.status = 'fechado'
  return [200, ticket]
}

