const MAXIMO_TENTATIVAS = 3

const chamadas = {}

function enviarEmail(pedidoId) {
  chamadas[pedidoId] = (chamadas[pedidoId] ?? 0) + 1

  if (pedidoId === 'falha-permanente') {
    const erro = new Error('endereço inválido')
    erro.temporario = false
    throw erro
  }

  if (pedidoId === 'falha-temporaria' && chamadas[pedidoId] < 3) {
    const erro = new Error('provedor indisponível')
    erro.temporario = true
    throw erro
  }

  return true
}

function zerar() {
  for (const chave of Object.keys(chamadas)) delete chamadas[chave]
}

function vezesChamado(pedidoId) {
  return chamadas[pedidoId] ?? 0
}

function processar(eventos) {
  const vistos = new Set()
  const enviados = []
  const ignorados = []
  const descartados = []

  for (const evento of eventos) {
    // A identidade e o eventoId: dois eventos sobre o mesmo pedido sao dois
    // trabalhos, e o mesmo evento duas vezes e um so.
    if (vistos.has(evento.eventoId)) {
      ignorados.push(evento.eventoId)
      continue
    }
    vistos.add(evento.eventoId)

    let ultimoErro = null

    for (let tentativa = 1; tentativa <= MAXIMO_TENTATIVAS; tentativa++) {
      try {
        enviarEmail(evento.pedidoId)
        enviados.push(evento.pedidoId)
        ultimoErro = null
        break
      } catch (erro) {
        ultimoErro = erro
        // Repetir erro permanente so gasta tentativa: ele nao melhora.
        if (!erro.temporario) break
      }
    }

    if (ultimoErro) {
      descartados.push({
        pedidoId: evento.pedidoId,
        motivo: ultimoErro.temporario ? 'tentativas' : 'permanente',
      })
    }
  }

  return { enviados, ignorados, descartados }
}

