const LINHAS = [
  { linha: 1, sku: 'ABC-1', nome: 'Caneta', preco: '4,50', quantidade: '10' },
  { linha: 2, sku: '', nome: 'Sem SKU', preco: '9,90', quantidade: '2' },
  { linha: 3, sku: 'ABC-2', nome: 'Caderno', preco: '19.90', quantidade: '5' },
  { linha: 4, sku: 'ABC-1', nome: 'Caneta azul', preco: '4,90', quantidade: '7' },
  { linha: 5, sku: 'ABC-3', nome: 'Borracha', preco: 'grátis', quantidade: '1' },
  { linha: 6, sku: 'ABC-4', nome: '', preco: '2,00', quantidade: '3' },
  { linha: 7, sku: 'ABC-5', nome: 'Lápis', preco: '1,50', quantidade: '0' },
  { linha: 8, sku: 'ABC-6', nome: 'Régua', preco: '-3,00', quantidade: '4' },
]

function comoNumero(valor) {
  // Planilha brasileira usa virgula; exportacao de sistema usa ponto.
  return Number(String(valor ?? '').trim().replace(',', '.'))
}

function importar(linhas) {
  // Set responde "ja vi este SKU?" sem percorrer o que ja passou.
  const vistos = new Set()
  const produtos = []
  const descartados = []

  for (const bruta of linhas) {
    const sku = String(bruta.sku ?? '').trim()
    const nome = String(bruta.nome ?? '').trim()
    const preco = comoNumero(bruta.preco)
    const quantidade = comoNumero(bruta.quantidade)

    const motivo =
      sku === ''
        ? 'sku ausente'
        : vistos.has(sku)
          ? 'sku repetido'
          : nome === ''
            ? 'nome ausente'
            : !(preco > 0)
              ? 'preço inválido'
              : !Number.isInteger(quantidade) || quantidade < 0
                ? 'quantidade inválida'
                : null

    if (motivo) {
      descartados.push({ linha: bruta.linha, motivo })
      continue
    }

    vistos.add(sku)
    produtos.push({ sku, nome, preco, quantidade })
  }

  return { produtos, descartados, total: linhas.length }
}

