TICKETS = [
    {"id": 1, "dono": "ana", "titulo": "impressora", "status": "aberto"},
    {"id": 2, "dono": "bruno", "titulo": "vpn", "status": "aberto"},
    {"id": 3, "dono": "ana", "titulo": "acesso", "status": "fechado"},
]

ana = {"id": "ana", "papel": "cliente"}
bruno = {"id": "bruno", "papel": "cliente"}
carla = {"id": "carla", "papel": "suporte"}
chefe = {"id": "chefe", "papel": "admin"}
estranho = {"id": "x", "papel": "diretor"}

# A tabela responde "o que este papel pode?" numa olhada, e acrescentar um
# papel e mudar dado, nao codigo.
CLIENTE = {"abrir_ticket", "ver_proprio"}
SUPORTE = CLIENTE | {"ver_todos", "fechar_ticket"}
ADMIN = SUPORTE | {"gerenciar_usuarios"}

PERMISSOES = {"cliente": CLIENTE, "suporte": SUPORTE, "admin": ADMIN}

NAO_ENCONTRADO = (404, {"erro": "não encontrado"})
SEM_PERMISSAO = (403, {"erro": "sem permissão"})


def pode(usuario, acao):
    # Padrao negar: papel ausente ou desconhecido cai no conjunto vazio.
    return acao in PERMISSOES.get(usuario.get("papel"), set())


def _visiveis(usuario):
    if pode(usuario, "ver_todos"):
        return list(TICKETS)
    return [t for t in TICKETS if t["dono"] == usuario.get("id")]


def listar(usuario):
    return 200, _visiveis(usuario)


def obter(usuario, ticket_id):
    # Procura so no que a pessoa ja pode ver: assim "nao e seu" e "nao existe"
    # saem pelo mesmo caminho, sem o codigo precisar lembrar de disfarcar.
    for ticket in _visiveis(usuario):
        if ticket["id"] == ticket_id:
            return 200, ticket
    return NAO_ENCONTRADO


def fechar(usuario, ticket_id):
    # Permissao da acao antes da existencia: quem nao pode fechar nada nao
    # deve descobrir o que existe tentando ids.
    if not pode(usuario, "fechar_ticket"):
        return SEM_PERMISSAO

    for ticket in _visiveis(usuario):
        if ticket["id"] == ticket_id:
            ticket["status"] = "fechado"
            return 200, ticket

    return NAO_ENCONTRADO

