challenges.solution:
let relogio = 0

const CUSTO = { pedido: 120, cliente: 40, relatorio: 900 }

function consultarOrigem(tipo, id) {
  relogio += CUSTO[tipo] ?? 10
  return { tipo, id, geradoEm: relogio }
}

function agora() {
  return relogio
}

const cache = new Map()
let buscas = 0
let acertos = 0
let duracoes = []

function zerar() {
  relogio = 0
  cache.clear()
  buscas = 0
  acertos = 0
  duracoes = []
}

const chaveDe = (tipo, id) => `${tipo}:${id}`

function buscar(tipo, id) {
  buscas += 1
  const chave = chaveDe(tipo, id)

  if (cache.has(chave)) {
    acertos += 1
    return cache.get(chave)
  }

  // A medicao envolve so a ida a origem: acerto nao tem duracao a medir.
  const inicio = agora()
  const valor = consultarOrigem(tipo, id)
  duracoes.push(agora() - inicio)

  cache.set(chave, valor)
  return valor
}

function invalidar(tipo, id) {
  cache.delete(chaveDe(tipo, id))
}

function invalidarTipo(tipo) {
  // Remove so as entradas daquele tipo: limpar tudo devolveria a lentidao
  // que o cache resolveu, a cada alteracao de qualquer entidade.
  const prefixo = `${tipo}:`
  for (const chave of [...cache.keys()]) {
    if (chave.startsWith(prefixo)) cache.delete(chave)
  }
}

function relatorio() {
  if (buscas === 0) return { buscas: 0, acertos: 0, taxaAcerto: 0, p95: 0 }

  const ordenadas = [...duracoes].sort((a, b) => a - b)
  const p95 = ordenadas.length === 0 ? 0 : ordenadas[Math.ceil(0.95 * ordenadas.length) - 1]

  return {
    buscas,
    acertos,
    taxaAcerto: Math.round((acertos / buscas) * 100),
    p95,
  }
}

