challenges.solution:
const FRETE_PADRAO = 2500
const FRETE_GRATIS_ACIMA_DE = 30000
const TETO_DESCONTO_PERCENTUAL = 20

const CUPONS = {
  PRIMEIRA: { tipo: 'percentual', valor: 10 },
  VOLTA15: { tipo: 'percentual', valor: 15 },
  MENOS50: { tipo: 'fixo', valor: 5000 },
  FRETEGRATIS: { tipo: 'frete' },
}

const regrasDe = (cupons) => cupons.map((nome) => CUPONS[nome]).filter(Boolean)

function subtotalDe(itens) {
  return itens.reduce((soma, item) => soma + item.preco * item.quantidade, 0)
}

function descontoDe(subtotal, regras) {
  const percentual = regras
    .filter((r) => r.tipo === 'percentual')
    .reduce((soma, r) => soma + r.valor, 0)

  const fixo = regras.filter((r) => r.tipo === 'fixo').reduce((soma, r) => soma + r.valor, 0)

  const bruto = Math.round((subtotal * percentual) / 100) + fixo

  // O teto vale sobre a SOMA, nao sobre cada cupom.
  const teto = Math.round((subtotal * TETO_DESCONTO_PERCENTUAL) / 100)
  return Math.min(bruto, teto)
}

function freteDe(subtotal, regras) {
  if (subtotal === 0) return 0
  // Decidido pelo subtotal, antes do desconto: desconto nao tira frete gratis.
  if (subtotal >= FRETE_GRATIS_ACIMA_DE) return 0
  if (regras.some((r) => r.tipo === 'frete')) return 0
  return FRETE_PADRAO
}

function calcular(itens, cupons = []) {
  const regras = regrasDe(cupons)

  const subtotal = subtotalDe(itens)
  const desconto = descontoDe(subtotal, regras)
  const frete = freteDe(subtotal, regras)

  return { subtotal, desconto, frete, total: Math.max(0, subtotal - desconto) + frete }
}
